    private void Update(SystemMetricsSnapshot s){var p=WidgetTheme.Resolve(item);WidgetTheme.Apply(root,p);var colors=new[]{WidgetTheme.Blend(p.Accent,WpfColor.FromRgb(105,188,255),.72),WidgetTheme.Blend(p.Accent,WpfColor.FromRgb(111,219,174),.72),WidgetTheme.Blend(p.Accent,WpfColor.FromRgb(195,145,255),.72)};var upload=WidgetTheme.Blend(p.Accent,WpfColor.FromRgb(255,116,116),.76);brandMark.Stroke=new SolidColorBrush(colors[0]);heading.Foreground=new SolidColorBrush(p.Muted);cpu.Update(s.Cpu,ProcessorClock.Read(),colors[0],p);ram.Update(s.Memory,Aux(s.Memory),colors[1],p);gpu.Update(s.Gpu,Aux(s.Gpu),colors[2],p);down.Update(s.Download,colors[0],p);up.Update(s.Upload,upload,p);((Border)rows.Children[4]).Background=new SolidColorBrush(WpfColor.FromArgb(55,p.Foreground.R,p.Foreground.G,p.Foreground.B));cpu.View.Visibility=item.SystemMonitor.ShowCpu?Visibility.Visible:Visibility.Collapsed;ram.View.Visibility=item.SystemMonitor.ShowMemory?Visibility.Visible:Visibility.Collapsed;gpu.View.Visibility=item.SystemMonitor.ShowGpu?Visibility.Visible:Visibility.Collapsed;down.View.Visibility=up.View.Visibility=item.SystemMonitor.ShowNetwork?Visibility.Visible:Visibility.Collapsed;}
